"""Small CSV parsing helper used by the reporting scripts."""


def parse(text: str) -> list[list[str]]:
    """Parse CSV text into a list of records, each a list of field strings."""
    rows = []
    i = 0
    n = len(text)

    while i < n:
        # Skip empty lines at start (but not mid-file empty lines that would be handled naturally)
        if text[i] == '\n':
            i += 1
            continue
        if text[i] == '\r' and i + 1 < n and text[i + 1] == '\n':
            i += 2
            continue

        row = []
        while True:
            if i >= n:
                break

            if text[i] == '"':
                # Quoted field
                i += 1  # skip opening quote
                field = ""
                while i < n:
                    if text[i] == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            # Escaped quote
                            field += '"'
                            i += 2
                        else:
                            # End of quoted field
                            i += 1  # skip closing quote
                            break
                    elif text[i] == '\r':
                        if i + 1 < n and text[i + 1] == '\n':
                            field += '\r\n'
                            i += 2
                        else:
                            field += '\r'
                            i += 1
                    elif text[i] == '\n':
                        field += '\n'
                        i += 1
                    else:
                        field += text[i]
                        i += 1

                row.append(field)
            else:
                # Unquoted field
                field = ""
                while i < n and text[i] != ',' and text[i] != '\n' and text[i] != '\r':
                    field += text[i]
                    i += 1
                row.append(field)

            # Check for end of record
            if i >= n:
                break

            if text[i] == ',':
                i += 1  # skip comma, continue to next field
            elif text[i] == '\r':
                if i + 1 < n and text[i + 1] == '\n':
                    i += 2  # skip \r\n
                else:
                    i += 1  # skip \r
                break  # end of record
            elif text[i] == '\n':
                i += 1  # skip \n
                break  # end of record

        if row or (i < n):
            # Only add non-empty rows, but handle last record without trailing newline
            if row:
                rows.append(row)

        # Handle case where file ends without newline after last record
        if i >= n:
            break

    return rows

