"""Small CSV parsing helper used by the reporting scripts."""


def parse(text: str) -> list[list[str]]:
    """Parse CSV text into a list of records, each a list of field strings."""
    rows = []
    i = 0
    n = len(text)

    while i < n:
        # Skip empty lines at the start
        if i == 0 and text[i] in '\r\n':
            i += 1
            continue

        row = []
        field = ""
        in_quotes = False

        while True:
            if i >= n:
                break

            ch = text[i]

            if in_quotes:
                if ch == '"':
                    # Check for escaped quote
                    if i + 1 < n and text[i + 1] == '"':
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        in_quotes = False
                        i += 1
                else:
                    field += ch
                    i += 1
            else:
                if ch == '"':
                    # Start of quoted field
                    in_quotes = True
                    i += 1
                elif ch == ',':
                    # End of field
                    row.append(field)
                    field = ""
                    i += 1
                elif ch == '\r':
                    # Handle \r\n or standalone \r
                    if i + 1 < n and text[i + 1] == '\n':
                        i += 2
                    else:
                        i += 1
                    row.append(field)
                    break
                elif ch == '\n':
                    # End of record
                    i += 1
                    row.append(field)
                    break
                else:
                    field += ch
                    i += 1

        if row or field:
            rows.append(row)

        # If we exited because we hit end of text while in a field
        if i >= n and field != "":
            # This shouldn't happen in normal flow, but handle it
            pass

    return rows

