                if i < n and text[i] == '\n':
                    i += 1
                break
            elif text[i] == '\n':
                i += 1
                break

            # Parse a field
            if text[i] == '"':
                # Quoted field
                i += 1  # Skip opening quote
                field = ""
                while i < n:
                    if text[i] == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            # Escaped quote
                            field += '"'
