from decimal import ROUND_FLOOR, ROUND_CEILING, Decimal

CENT = Decimal("0.01")


def to_decimal(value):
    """Convert an int, str or Decimal to Decimal. Floats are rejected to avoid binary rounding surprises."""
    if isinstance(value, float):
        raise TypeError("use str or Decimal for money amounts, not float")
    return Decimal(value)


def round_money(value):
    """Round an amount to whole cents."""
    d = to_decimal(value)
    # Scale to cents
    scaled = d * 100
    # Get the integral part (floor for positive, ceiling for negative)
    if scaled >= 0:
        floored = scaled.to_integral_value(rounding=ROUND_FLOOR)
    else:
        floored = scaled.to_integral_value(rounding=ROUND_CEILING)
    remainder = scaled - floored

    # Round half away from zero
    if remainder == Decimal("0.5"):
        # Exactly half - round away from zero
        if scaled > 0:
            floored += 1
        else:
            floored -= 1
    elif remainder > Decimal("0.5"):
        # More than half - round away from zero
        if scaled >= 0:
            floored += 1
        else:
            floored -= 1
    # Else less than half - keep floored

    return floored / 100


def format_money(value, currency="EUR"):
    """Format an amount for printing, e.g. '1,234.50 EUR'."""
    return f"{round_money(value):,.2f} {currency}"

