"""Small CSV parsing helper used by the reporting scripts."""


def parse(text: str) -> list[list[str]]:
    """Parse CSV text into a list of records, each a list of field strings."""
    rows = []
    i = 0
    n = len(text)

    while i < n:
        # Skip any leading empty lines (but track them as empty records if between data)
        row = []
        field = ""
        in_quotes = False

        while i < n:
            char = text[i]

            if in_quotes:
                if char == '"':
                    # Check for escaped quote ("")
                    if i + 1 < n and text[i + 1] == '"':
                        field += '"'
                        i += 2
                        continue
                    else:
                        # End of quoted field
                        in_quotes = False
                        i += 1
                        continue
                else:
                    field += char
                    i += 1
            else:
                if char == '"':
                    # Start of quoted field
                    in_quotes = True
                    i += 1
                elif char == ',':
                    # End of field
                    row.append(field)
                    field = ""
                    i += 1
                elif char == '\r':
                    # Handle CRLF or CR line ending
                    if i + 1 < n and text[i + 1] == '\n':
                        i += 2  # Skip CRLF
                    else:
                        i += 1  # Skip CR only
                    break
                elif char == '\n':
                    # LF line ending
                    i += 1
                    break
                else:
                    field += char
                    i += 1

        # Handle the last field after loop ends
        if not row or field != "" or i > 0:
            # If we have a non-empty field at end of input, add it
            if field != "" or (row and field == ""):
                row.append(field)

        # Only add row if we parsed something meaningful
        # A row with just an empty string from trailing newline should be skipped
        # But we need to be careful about actual empty records
        if row:
            # Check if this is just a trailing empty line (no actual content)
            if len(row) == 1 and row[0] == "":
                # Check if there's more content after this point
                remaining = text[i:].lstrip('\r\n')
                if remaining == "":
                    # This is trailing whitespace, skip
                    pass
                else:
                    # There's more content, this might be intentional
                    rows.append(row)
            else:
                rows.append(row)

    return rows

"""Small CSV parsing helper used by the reporting scripts."""


def parse(text: str) -> list[list[str]]:
    """Parse CSV text into a list of records, each a list of field strings."""
    rows = []
    i = 0
    n = len(text)

    while i < n:
        # Skip leading empty lines (but preserve empty records within data)
        row = []

        # Check if we're at end of file
        if i >= n:
            break

        # Parse fields until end of record
        while True:
            # Skip carriage return if present (CRLF handling)
            if i < n and text[i] == '\r':
                i += 1

            # Handle end of input
            if i >= n:
                row.append("")
                break

            # Handle end of line (LF)
            if text[i] == '\n':
                i += 1
                break

            # Check for quoted field
            if text[i] == '"':
                field = ""
                i += 1  # skip opening quote

                while i < n:
                    if text[i] == '"':
                        # Check for escaped quote
                        if i + 1 < n and text[i + 1] == '"':
                            field += '"'
                            i += 2  # skip both quotes
                        else:
                            # End of quoted field
                            i += 1  # skip closing quote
                            break
                    elif text[i] == '\r':
                        # Skip CR inside quoted field
                        i += 1
                    else:
                        field += text[i]
                        i += 1

                row.append(field)

                # After quoted field, check for comma or end of line
                if i < n:
                    if text[i] == '\r':
                        i += 1
                    if i < n and text[i] == '\n':
                        i += 1
                        break
                    elif text[i] == ',':
                        i += 1
                        continue
                    else:
                        # Unexpected character after closing quote
                        break
            else:
                # Unquoted field - read until comma or end of line
                field = ""
                while i < n:
                    c = text[i]
                    if c == ',':
                        i += 1
                        break
                    elif c == '\n':
                        row.append(field)
                        i += 1
                        break
                    elif c == '\r':
                        row.append(field)
                        i += 1
                        break
                    else:
                        field += c
                        i += 1
                else:
                    # Reached end of input
                    row.append(field)
                    break
                continue

            break

        # Only add non-empty rows (skip completely empty lines at start/end)
        # But include rows with actual content (even if all fields are empty strings)
        if row:
            rows.append(row)

    return rows

