                while i < n and text[i] != ',' and text[i] != '\n' and text[i] != '\r':
                    field += text[i]
                    i += 1
                row.append(field)
                ended_with_comma = False

                # After unquoted field, check what follows
                if i < n and text[i] == ',':
                    i += 1  # consume separator comma
                    ended_with_comma = True

        # If row ended with a comma, add trailing empty field
        if ended_with_comma:
            row.append("")

        if row:
            rows.append(row)

    return rows
